-
-                // AOSP / many OEM clocks
-                Intent("android.intent.action.SHOW_ALARMS"),
-
-                // Last resort: let user choose
-                Intent(Intent.ACTION_MAIN).addCategory("android.intent.category.APP_ALARM")
